--
-- Table structure for table `th_est_estimate`
--

DROP TABLE IF EXISTS `th_est_estimate`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `th_est_estimate` (
  `est_id` bigint NOT NULL AUTO_INCREMENT,
  `est_proj_id` bigint NOT NULL,
  `est_buffer_percent` bigint NOT NULL,
  `est_buffer_margin` bigint NOT NULL,
  `est_start` date DEFAULT NULL,
  `est_end` date DEFAULT NULL,
  `est_cost` decimal(11,2) DEFAULT NULL,
  `est_billed` decimal(11,2) DEFAULT NULL,
  `est_time` decimal(11,2) DEFAULT NULL,
  `est_remarks` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `est_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT 'C',
  `Active` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'Y',
  `EntryBy` bigint NOT NULL,
  `EntryDate` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `ModBy` int DEFAULT NULL,
